                this.frameCounter = 0;
                this.instructionsExecuted = 0;
            }

            loadFontSet() {
                // Font set: 5 bytes per character, 16 characters
                const fontSet = [
                    0xF0, 0x90, 0x90, 0x90, 0xF0, // 0
                    0x20, 0x60, 0x20, 0x20, 0x70, // 1
                    0xF0, 0x10, 0xF0, 0x80, 0xF0, // 2
                    0xF0, 0x10, 0xF0, 0x10, 0xF0, // 3
                    0x90, 0x90, 0xF0, 0x10, 0x10, // 4
                    0xF0, 0x80, 0xF0, 0x10, 0xF0, // 5
                    0xF0, 0x80, 0xF0, 0x90, 0xF0, // 6
                    0xF0, 0x10, 0x20, 0x40, 0x40, // 7
                    0xF0, 0x90, 0xF0, 0x90, 0xF0, // 8
                    0xF0, 0x90, 0xF0, 0x10, 0xF0, // 9
                    0xF0, 0x90, 0xF0, 0x90, 0x90, // A
                    0xE0, 0x90, 0xE0, 0x90, 0xE0, // B
                    0xF0, 0x80, 0x80, 0x80, 0xF0, // C
                    0xE0, 0x90, 0x90, 0x90, 0xE0, // D
                    0xF0, 0x80, 0xF0, 0x80, 0xF0, // E
                    0xF0, 0x80, 0xF0, 0x80, 0x80  // F
                ];

                // Load font set at 0x000
                for (let i = 0; i < fontSet.length; i++) {
                    this.memory[i] = fontSet[i];
                }
            }

            loadROM(data) {
                // Clear memory (except font set)
                for (let i = 0x50; i < 4096; i++) {
                    this.memory[i] = 0;
                }

                // Load ROM starting at 0x200
                for (let i = 0; i < data.length && i < 4096 - 0x200; i++) {
                    this.memory[0x200 + i] = data[i];
                }

                // Reset emulator state
                this.pc = 0x200;
                this.stack = [];
                this.stackDepth = 0;
                this.v.fill(0);
                this.I = 0;
                this.delayTimer = 0;
                this.soundTimer = 0;
                this.display.fill(0);

                // Update display
                this.updateDisplay();
            }

            executeInstruction() {
                // Read 2-byte instruction
                this.instruction = (this.memory[this.pc] << 8) | this.memory[this.pc + 1];

                // Decode instruction
                const nnn = this.instruction & 0x0FFF;
                const n = this.instruction & 0x000F;
                const x = (this.instruction >> 8) & 0x000F;
                const y = (this.instruction >> 4) & 0x000F;
                const kk = this.instruction & 0x00FF;

                // Update PC for next instruction
                this.pc += 2;

                // Execute instruction
                switch (this.instruction >> 12) {
                    case 0x0:
                        if (this.instruction === 0x00E0) {
                            // 00E0: CLS - Clear the display
                            this.display.fill(0);
                        } else if (this.instruction === 0x00EE) {
                            // 00EE: RET - Return from subroutine
                            this.pc = this.stack.pop();
                            this.stackDepth--;
                        }
                        break;
                    case 0x1:
                        // 1NNN: JP addr - Jump to location nnn
                        this.pc = nnn;
                        break;
                    case 0x2:
                        // 2NNN: CALL addr - Call subroutine at nnn
                        this.stack.push(this.pc);
                        this.stackDepth++;
                        this.pc = nnn;
                        break;
                    case 0x3:
                        // 3XKK: SE Vx, byte - Skip next instruction if Vx == kk
                        if (this.v[x] === kk) {
                            this.pc += 2;
                        }
                        break;
                    case 0x4:
                        // 4XKK: SNE Vx, byte - Skip next instruction if Vx != kk
                        if (this.v[x] !== kk) {
                            this.pc += 2;
                        }
                        break;
                    case 0x5:
                        // 5XY0: SE Vx, Vy - Skip next instruction if Vx == Vy
                        if (this.v[x] === this.v[y]) {
                            this.pc += 2;
                        }
                        break;
                    case 0x6:
                        // 6XKK: LD Vx, byte - Set Vx = kk
                        this.v[x] = kk;
                        break;
                    case 0x7:
                        // 7XKK: ADD Vx, byte - Set Vx = Vx + kk
                        this.v[x] = (this.v[x] + kk) & 0xFF;
                        break;
                    case 0x8:
                        switch (n) {
                            case 0x0:
                                // 8XY0: LD Vx, Vy - Set Vx = Vy
                                this.v[x] = this.v[y];
                                break;
                            case 0x1:
                                // 8XY1: OR Vx, Vy - Set Vx = Vx OR Vy
                                this.v[x] |= this.v[y];
                                break;
                            case 0x2:
                                // 8XY2: AND Vx, Vy - Set Vx = Vx AND Vy
                                this.v[x] &= this.v[y];
                                break;
                            case 0x3:
                                // 8XY3: XOR Vx, Vy - Set Vx = Vx XOR Vy
                                this.v[x] ^= this.v[y];
                                break;
                            case 0x4:
                                // 8XY4: ADD Vx, Vy - Set Vx = Vx + Vy, set VF = carry
                                const sum = this.v[x] + this.v[y];
                                this.v[x] = sum & 0xFF;
                                this.v[0xF] = sum > 0xFF ? 1 : 0;
                                break;
                            case 0x5:
                                // 8XY5: SUB Vx, Vy - Set Vx = Vx - Vy, set VF = NOT borrow
                                this.v[0xF] = this.v[x] > this.v[y] ? 1 : 0;
                                this.v[x] = (this.v[x] - this.v[y]) & 0xFF;
                                break;
                            case 0x6:
                                // 8XY6: SHR Vx {, Vy} - Set Vx = Vx >> 1, set VF = least significant bit of Vx
                                this.v[0xF] = this.v[x] & 0x01;
                                this.v[x] >>= 1;
                                break;
                            case 0x7:
                                // 8XY7: SUBN Vx, Vy - Set Vx = Vy - Vx, set VF = NOT borrow
                                this.v[0xF] = this.v[y] > this.v[x] ? 1 : 0;
                                this.v[x] = (this.v[y] - this.v[x]) & 0xFF;
                                break;
                            case 0xE:
                                // 8XYE: SHL Vx {, Vy} - Set Vx = Vx << 1, set VF = most significant bit of Vx
                                this.v[0xF] = (this.v[x] >> 7) & 0x01;
                                this.v[x] = (this.v[x] << 1) & 0xFF;
                                break;
                        }
                        break;
                    case 0x9:
                        // 9XY0: SNE Vx, Vy - Skip next instruction if Vx != Vy
                        if (this.v[x] !== this.v[y]) {
                            this.pc += 2;
                        }
                        break;
                    case 0xA:
                        // ANNN: LD I, addr - Set I = nnn
                        this.I = nnn;
                        break;
                    case 0xB:
                        // BNNN: JP V0, addr - Jump to location nnn + V0
                        this.pc = nnn + this.v[0];
                        break;
                    case 0xC:
                        // CXKK: RND Vx, byte - Set Vx = random byte AND kk
                        const random = Math.floor(Math.random() * 256);
                        this.v[x] = random & kk;
                        break;
                    case 0xD:
                        // DXYN: DRW Vx, Vy, nibble - Display sprite at (Vx, Vy) with height N
                        // This instruction sets VF to 1 if any pixel is flipped from 1 to 0
                        this.v[0xF] = 0;
                        const width = 8;
                        const height = n;

                        let xCoord = this.v[x] % 64;
                        let yCoord = this.v[y] % 32;

                        for (let row = 0; row < height; row++) {
                            const spritePixel = this.memory[this.I + row];

                            for (let col = 0; col < width; col++) {
                                if ((spritePixel & (0x80 >> col)) !== 0) {
                                    const pixelIndex = (yCoord + row) * 64 + (xCoord + col);

                                    if (pixelIndex >= 0 && pixelIndex < this.display.length) {
                                        // XOR the pixel
                                        if (this.display[pixelIndex] === 1) {
                                            this.display[pixelIndex] = 0;
                                            this.v[0xF] = 1; // Collision detected
                                        } else {
                                            this.display[pixelIndex] = 1;
                                        }
                                    }
                                }
                            }
                        }
                        break;
                    case 0xE:
                        switch (kk) {
                            case 0x9E:
                                // EX9E: SKP Vx - Skip next instruction if key with value of Vx is pressed
                                if (this.keys[this.v[x]] === 1) {
                                    this.pc += 2;
                                }
                                break;
                            case 0xA1:
                                // EXA1: SKNP Vx - Skip next instruction if key with value of Vx is not pressed
                                if (this.keys[this.v[x]] === 0) {
                                    this.pc += 2;
                                }
                                break;
                        }
                        break;
                    case 0xF:
                        switch (kk) {
                            case 0x07:
                                // FX07: LD Vx, DT - Set Vx = delay timer value
                                this.v[x] = this.delayTimer;
                                break;
                            case 0x0A:
                                // FX0A: LD Vx, K - Wait for key press, store in Vx
                                // This is implemented in the main loop
                                break;
                            case 0x15:
                                // FX15: LD DT, Vx - Set delay timer = Vx
                                this.delayTimer = this.v[x];
                                break;
                            case 0x18:
                                // FX18: LD ST, Vx - Set sound timer = Vx
                                this.soundTimer = this.v[x];
                                break;
                            case 0x1E:
                                // FX1E: ADD I, Vx - Set I = I + Vx
                                const newI = this.I + this.v[x];
                                this.v[0xF] = newI > 0xFFF ? 1 : 0; // Set VF if overflow
                                this.I = newI & 0xFFF;
                                break;
                            case 0x29:
                                // FX29: LD F, Vx - Set I = location of sprite for digit Vx
                                this.I = this.v[x] * 5; // Each font is 5 bytes
                                break;
                            case 0x33:
                                // FX33: LD B, Vx - Store BCD representation of Vx in memory
                                // Vx contains a decimal number, store hundreds, tens, units in I, I+1, I+2
                                const value = this.v[x];
                                this.memory[this.I] = Math.floor(value / 100);
                                this.memory[this.I + 1] = Math.floor((value / 10) % 10);
                                this.memory[this.I + 2] = value % 10;
                                break;
                            case 0x55:
                                // FX55: LD [I], Vx - Store registers V0 through Vx in memory starting at I
                                for (let i = 0; i <= x; i++) {
                                    this.memory[this.I + i] = this.v[i];
                                }
                                this.I += x + 1;
                                break;
                            case 0x65:
                                // FX65: LD Vx, [I] - Read registers V0 through Vx from memory starting at I
                                for (let i = 0; i <= x; i++) {
                                    this.v[i] = this.memory[this.I + i];
                                }
                                this.I += x + 1;
                                break;
                        }
                        break;
                }

                // Update the instruction display
                this.updateDebugger();
            }

            updateDisplay() {
                // Update the canvas display
                const canvas = document.getElementById('chip8-canvas');
                const ctx = canvas.getContext('2d');
                const imageData = ctx.createImageData(64, 32);

                for (let i = 0; i < 64 * 32; i++) {
                    const pixel = this.display[i];
                    const color = pixel ? 255 : 0;
                    imageData.data[i * 4] = color;     // R
                    imageData.data[i * 4 + 1] = color; // G
                    imageData.data[i * 4 + 2] = color; // B
                    imageData.data[i * 4 + 3] = 255;   // A
                }

                ctx.putImageData(imageData, 0, 0);
            }

