                document.getElementById('sound-timer').textContent = this.soundTimer;

                // Stack
                let stackStr = '[';
                if (this.stack.length > 0) {
                    stackStr += this.stack.map(addr => '0x' + addr.toString(16).toUpperCase().padStart(4, '0')).join(', ');
                }
                stackStr += ']';
                document.getElementById('stack').textContent = stackStr;

                document.getElementById('stack-depth').textContent = this.stackDepth;

                // Current instruction
                const instructionHex = this.instruction.toString(16).toUpperCase().padStart(4, '0');
                document.getElementById('current-instruction').textContent = '0x' + instructionHex;

                // Memory
                let memoryStr = '';
                for (let i = 0; i < 16; i++) {
                    const addr = 0x200 + i;
                    memoryStr += this.memory[addr].toString(16).toUpperCase().padStart(2, '0') + ' ';
                }
                document.getElementById('memory').textContent = memoryStr;
            }

            updateTimers() {
                // Timers count down at 60 Hz
                if (this.delayTimer > 0) {
                    this.delayTimer--;
                }

                if (this.soundTimer > 0) {
                    this.soundTimer--;
                    // In a real implementation, this would trigger a sound
                }
            }

            handleKeyPress(key) {
                const chip8Key = this.keyMap[key.toLowerCase()];
                if (chip8Key !== undefined) {
                    this.keys[chip8Key] = 1;
                }
            }

            handleKeyRelease(key) {
                const chip8Key = this.keyMap[key.toLowerCase()];
                if (chip8Key !== undefined) {
                    this.keys[chip8Key] = 0;
                }
            }

            // Wait for key press (for FX0A instruction)
            waitForKeypress() {
                // This will be handled in the main loop
                // We need to pause execution until a key is pressed
                // In this implementation, we'll just set the PC back and wait
                // This is a simplified approach
                return false;
            }
        }

        // Initialize emulator
        const chip8 = new CHIP8();

        // Set up canvas
        const canvas = document.getElementById('chip8-canvas');
        const ctx = canvas.getContext('2d');

        // Set up keyboard event listeners
        document.addEventListener('keydown', (e) => {
            chip8.handleKeyPress(e.key);
        });

        document.addEventListener('keyup', (e) => {
            chip8.handleKeyRelease(e.key);
        });

        // Set up keyboard buttons
        document.querySelectorAll('.key').forEach(button => {
            button.addEventListener('mousedown', () => {
                const key = button.getAttribute('data-key');
                chip8.handleKeyPress(key);
            });

            button.addEventListener('mouseup', () => {
                const key = button.getAttribute('data-key');
                chip8.handleKeyRelease(key);
