            document.getElementById('pause-btn').textContent = chip8.paused ? 'Resume' : 'Pause';
        });

        document.getElementById('step-btn').addEventListener('click', () => {
            if (!chip8.running && !chip8.paused) {
                chip8.executeInstruction();
                chip8.updateDisplay();
                chip8.updateDebugger();
            } else if (chip8.paused) {
                chip8.executeInstruction();
                chip8.updateDisplay();
                chip8.updateDebugger();
