        // Main emulation loop
        function emulationLoop() {
            if (chip8.running && !chip8.paused) {
                // Execute multiple instructions per frame based on speed
                for (let i = 0; i < chip8.speed; i++) {
                    // Check if we're waiting for a key press
                    const currentInstruction = (chip8.memory[chip8.pc] << 8) | chip8.memory[chip8.pc + 1];
                    const x = (currentInstruction >> 8) & 0x000F;
                    const kk = currentInstruction & 0x00FF;

                    if ((currentInstruction >> 12) === 0xF && kk === 0x0A) {
                        // FX0A: LD Vx, K - Wait for key press
                        // Check if any key is pressed
                        let keyPressed = false;
                        for (let k = 0; k < 16; k++) {
                            if (chip8.keys[k] === 1) {
                                chip8.v[x] = k;
                                keyPressed = true;
