                            }
                        }

                        if (!keyPressed) {
                            // No key pressed, don't execute instruction
                            break;
                        }
                    }

                    chip8.executeInstruction();
                }

                // Update timers at 60 Hz (approximately)
                chip8.updateTimers();

                // Update display
                chip8.updateDisplay();

                // Update debugger
                chip8.updateDebugger();
            }

            // Schedule next frame
            requestAnimationFrame(emulationLoop);
        }

